const rag = $('Query Recruiting Knowledge Base').first().json;
const input = $('When Executed by Another Workflow').first().json;
const answer = String(rag.response || '').trim();
const jobId = String(input.job_id || '').trim();
const fallback = "I don't know. I could not find enough information in the indexed documentation.";

function normalize(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

const normalizedAnswer = normalize(answer);
const normalizedJobId = normalize(jobId);
const noCoverage =
  normalizedAnswer.includes('i could not find enough information') ||
  normalizedAnswer.includes('i cannot retrieve the requested information') ||
  normalizedAnswer.includes('no indexed documentation was provided');
const mentionsRequestedJob = normalizedJobId.length > 0 && normalizedAnswer.includes(normalizedJobId);
const coverage = answer.length > 0 && !noCoverage && mentionsRequestedJob;

return [{
  json: {
    job_id: jobId,
    rag_executed: true,
    rag_coverage: coverage,
    rag_metadata: null,
    rubric: coverage ? answer : '',
    rag_context: coverage ? answer : '',
    fallback: coverage ? '' : fallback,
    rag_query: `Complete authorized context for job ${jobId}`,
    retrieved_at: new Date().toISOString()
  }
}];

const outputData = $('Prepare RAG Output').first().json;
const requestedJobId = String(outputData.job_id || '').trim();
const fallback = "I don't know. I could not find enough information in the indexed documentation.";
let chunks = [];

try {
  chunks = $('Recruiting Vector Store').all();
} catch (error) {
  chunks = [];
}

const sources = [];

function collectMetadata(value) {
  if (!value || typeof value !== 'object') return;
  if (value.document_id && value.document_title && value.version && value.job_id && value.source_file) {
    sources.push({
      document_id: String(value.document_id),
      document_title: String(value.document_title),
      version: String(value.version),
      job_id: String(value.job_id),
      source_file: String(value.source_file)
    });
  }
  for (const child of Object.values(value)) {
    if (child && typeof child === 'object') collectMetadata(child);
  }
}

for (const item of chunks) collectMetadata(item.json);

const uniqueSources = Array.from(new Map(
  sources.map(source => [[source.document_id, source.version, source.job_id, source.source_file].join('|'), source])
).values());
const validSources = uniqueSources.filter(source => source.job_id === requestedJobId);
const validCoverage = outputData.rag_executed === true && outputData.rag_coverage === true && validSources.length > 0;

return [{
  json: {
    ...outputData,
    rag_coverage: validCoverage,
    rubric: validCoverage ? outputData.rubric : '',
    rag_context: validCoverage ? outputData.rag_context : '',
    sources: validCoverage ? validSources : [],
    fallback: validCoverage ? '' : fallback,
    metadata_validated: validCoverage
  }
}];
